contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val) public {
        require(true);

        c.SetMinSum(val); if (__ESBMC_reverted()) return;

        uint minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { initReverted = true; } else { initReverted = false; }

        uint minAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        bool setMinSumReverted;
        c.SetMinSum(val); bool __rev1 = __ESBMC_reverted(); if (__rev1) { setMinSumReverted = true; } else { setMinSumReverted = false; }

        assert(!initReverted && minBefore == minAfter && setMinSumReverted);
    }

    receive() external payable {}
}

