pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val) internal {
        vm.assume(true);
        try c.SetMinSum(val) {} catch { return; }
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        bool initReverted;
        try c.Initialized() { initReverted = false; } catch { initReverted = true; }
        uint256 minAfter;
        try c.MinSum() returns (uint256 __r) { minAfter = __r; } catch { return; }
        bool setMinSumReverted;
        try c.SetMinSum(val) { setMinSumReverted = false; } catch { setMinSumReverted = true; }
        assertTrue(!initReverted && minBefore == minAfter && setMinSumReverted);
    }

    function testFuzz_run(uint256 val) public {
        _run(val);
    }

    receive() external payable {}
}
